#!/usr/bin/env python3
"""Public fixtures only. Runs the CLI through bounded, ordinary OS pipes."""
import argparse
import ctypes
import errno
import json
import math
import os
from pathlib import Path
import resource
import selectors
import signal
import stat
import subprocess
import sys
import time

CAP_OUT = 512 * 1024 * 1024
CAP_ERR = 1024 * 1024
LIBC = ctypes.CDLL(None, use_errno=True)
ACTIVE = set()


def prctl(option, argument):
    if LIBC.prctl(ctypes.c_int(option), ctypes.c_ulong(argument),
                  ctypes.c_ulong(0), ctypes.c_ulong(0), ctypes.c_ulong(0)) != 0:
        number = ctypes.get_errno()
        raise OSError(number, os.strerror(number))


def supervise():
    if os.uname().machine != 'x86_64':
        raise RuntimeError('The public development profile requires Linux x86-64.')
    try:
        os.kill(os.getpid(), 0)  # Check the supervisor-only signal permission.
        prctl(36, 1)  # PR_SET_CHILD_SUBREAPER: adopt orphaned descendants.
    except OSError as exc:
        raise RuntimeError('Public supervisor needs the development overlay in WORKER-PROFILE.md.') from exc


def candidate_filter():
    # Only the supervisor gets the development overlay permissions. Children
    # cannot leave their process group, even through a raw syscall or exec.
    class Filter(ctypes.Structure):
        _fields_ = [('code', ctypes.c_ushort), ('jt', ctypes.c_ubyte),
                    ('jf', ctypes.c_ubyte), ('k', ctypes.c_uint)]
    class Program(ctypes.Structure):
        _fields_ = [('length', ctypes.c_ushort), ('filters', ctypes.POINTER(Filter))]
    instructions = [(0x20, 0, 0, 4), (0x15, 1, 0, 0xc000003e),
                    (0x06, 0, 0, 0x80000000), (0x20, 0, 0, 0),
                    (0x35, 0, 1, 0x40000000), (0x06, 0, 0, 0x80000000)]
    for syscall in (62, 200, 234, 109, 112):  # kill/tkill/tgkill/setpgid/setsid
        instructions += [(0x15, 0, 1, syscall), (0x06, 0, 0, 0x00050000 | errno.EPERM)]
    instructions += [(0x06, 0, 0, 0x7fff0000)]
    filters = (Filter * len(instructions))(*(Filter(*item) for item in instructions))
    program = Program(len(filters), filters)
    prctl(38, 1)  # PR_SET_NO_NEW_PRIVS
    if LIBC.prctl(22, 2, ctypes.byref(program), 0, 0) != 0:
        number = ctypes.get_errno()
        raise OSError(number, os.strerror(number))


def pairs(items):
    value = {}
    for key, item in items:
        if key in value:
            raise ValueError("duplicate key")
        value[key] = item
    return value


def strict_json(raw):
    def bad_constant(value):
        raise ValueError("non-finite number")
    def finite_float(value):
        number = float(value)
        if not math.isfinite(number):
            raise ValueError("non-finite number")
        return number
    return json.loads(raw.decode("utf-8"), object_pairs_hook=pairs,
                      parse_constant=bad_constant, parse_float=finite_float)


def child_limits(mask):
    os.setpgid(0, 0)
    for kind, limits in [(resource.RLIMIT_AS, (2 << 30, 2 << 30)),
                         (resource.RLIMIT_CPU, (180, 181)),
                         (resource.RLIMIT_NPROC, (64, 64)),
                         (resource.RLIMIT_NOFILE, (256, 256)),
                         (resource.RLIMIT_FSIZE, (64 << 20, 64 << 20)),
                         (resource.RLIMIT_STACK, (8 << 20, resource.RLIM_INFINITY)),
                         (resource.RLIMIT_CORE, (0, 0))]:
        resource.setrlimit(kind, limits)
    candidate_filter()
    signal.pthread_sigmask(signal.SIG_SETMASK, mask)


def stop(child):
    # The group leader is deliberately not reaped before signalling: its PID
    # reserves the group identity. No UID-wide or unrelated-process signals.
    mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGINT, signal.SIGTERM})
    try:
        if getattr(child, '_public_cleaned', False):
            return
        if not hasattr(child, '_public_cleanup_deadline'):
            child._public_cleanup_deadline = time.monotonic() + 5
        deadline = child._public_cleanup_deadline
        if not getattr(child, '_public_signalled', False):
            try:
                os.killpg(child.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            child._public_signalled = True
        child.wait(timeout=max(.001, deadline - time.monotonic()))
        while True:
            try:
                pid, _ = os.waitpid(-child.pid, os.WNOHANG)
            except ChildProcessError:
                child._public_cleaned = True
                return
            if time.monotonic() >= deadline:
                raise RuntimeError('Public descendant cleanup did not complete; no result accepted.')
            if pid == 0:
                time.sleep(.01)
    finally:
        signal.pthread_sigmask(signal.SIG_SETMASK, mask)


def wait_exit(child, deadline):
    # WNOWAIT preserves the leader PID until stop() owns cleanup of the group.
    while True:
        result = os.waitid(os.P_PID, child.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT)
        if result is not None:
            return result.si_status if result.si_code == os.CLD_EXITED else -result.si_status
        if time.monotonic() >= deadline:
            raise ValueError('wall timeout')
        time.sleep(min(.01, max(0, deadline - time.monotonic())))


def run_child(candidate, data):
    if os.geteuid() == 0:
        raise RuntimeError("Refusing root candidate execution; run in the task container or a nonprivileged sandbox.")
    supervise()
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C", "LC_ALL": "C",
           "HOME": "/workspace", "TMPDIR": "/workspace/tmp",
           "PYTHONDONTWRITEBYTECODE": "1", "PYTHONUNBUFFERED": "1",
           "PYTHONHASHSEED": "0", "OMP_NUM_THREADS": "1",
           "OPENBLAS_NUM_THREADS": "1", "MKL_NUM_THREADS": "1"}
    selector = selectors.DefaultSelector()
    child = None
    streams = []
    captured = [bytearray(), bytearray()]
    offset = 0
    started = time.monotonic()
    try:
        mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGINT, signal.SIGTERM})
        try:
            child = subprocess.Popen([sys.executable, "-I", "-B", str(candidate)],
                                     stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                     stderr=subprocess.PIPE, close_fds=True,
                                     preexec_fn=lambda: child_limits(mask), env=env)
            ACTIVE.add(child)
            streams = [child.stdin, child.stdout, child.stderr]
        except subprocess.SubprocessError as exc:
            raise RuntimeError('Candidate setup failed; use the development overlay in WORKER-PROFILE.md.') from exc
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, mask)
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        selector.register(child.stdin, selectors.EVENT_WRITE, -1)
        selector.register(child.stdout, selectors.EVENT_READ, 0)
        selector.register(child.stderr, selectors.EVENT_READ, 1)
        while selector.get_map():
            left = 120 - (time.monotonic() - started)
            if left <= 0:
                raise ValueError("wall timeout")
            for key, _ in selector.select(min(left, 0.1)):
                stream, index = key.fileobj, key.data
                if index == -1:
                    try:
                        count = os.write(stream.fileno(), data[offset:offset + 65536])
                        offset += count
                    except BrokenPipeError:
                        offset = len(data)
                    except BlockingIOError:
                        continue
                    if offset == len(data):
                        selector.unregister(stream)
                        stream.close()
                else:
                    limit = (CAP_OUT, CAP_ERR)[index]
                    try:
                        chunk = os.read(stream.fileno(), min(65536, limit - len(captured[index]) + 1))
                    except BlockingIOError:
                        continue
                    if not chunk:
                        selector.unregister(stream)
                        stream.close()
                    elif len(chunk) + len(captured[index]) > limit:
                        raise ValueError(("stdout", "stderr")[index] + " limit")
                    else:
                        captured[index].extend(chunk)
        code = child.returncode if child.returncode is not None else wait_exit(child, started + 120)
        if code != 0:
            raise ValueError("candidate exited " + str(code))
        value = strict_json(bytes(captured[0]))
        if not isinstance(value, dict):
            raise ValueError("output is not an object")
        return value
    finally:
        try:
            if child is not None:
                stop(child)
                ACTIVE.discard(child)
        finally:
            selector.close()
            for stream in streams:
                stream.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("candidate", type=Path, help="project directory containing campaign_cli.py and src/")
    args = parser.parse_args()
    project = args.candidate.absolute()
    if project.is_symlink() or not project.is_dir():
        raise ValueError("candidate must be a regular project directory")
    total = 0
    entries = 0
    for path in project.rglob("*"):
        info = path.lstat(); entries += 1
        if path.is_symlink() or not (stat.S_ISREG(info.st_mode) or stat.S_ISDIR(info.st_mode)):
            raise ValueError("project contains a non-regular entry")
        if stat.S_ISREG(info.st_mode):
            if info.st_nlink != 1: raise ValueError("project contains a hard link")
            total += info.st_size
    if total > 8 * 1024 * 1024 or entries > 256:
        raise ValueError("project exceeds submission bounds")
    candidate = project / "campaign_cli.py"
    candidate.read_bytes().decode("utf-8")
    files = sorted((Path(__file__).parent / "examples").glob("*.input.json"))
    if not files:
        raise RuntimeError("public fixtures missing")
    passed = 0
    for path in files:
        try:
            actual = run_child(candidate, path.read_bytes())
            expected = strict_json(path.with_name(path.name.replace(".input.", ".expected.")).read_bytes())
            # JSON serialization distinguishes bool/int and rejects numeric aliases.
            if json.dumps(actual, sort_keys=True) != json.dumps(expected, sort_keys=True):
                raise ValueError("response differs from public expectation")
            passed += 1
            print("PASS " + path.name)
        except (ValueError, OSError, subprocess.TimeoutExpired) as exc:
            print("FAIL " + path.name + ": " + str(exc))
    print(str(passed) + "/" + str(len(files)) + " public fixtures passed")
    return 0 if passed == len(files) else 1


if __name__ == "__main__":
    def interrupted(signum, frame):
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, signal.SIG_IGN)
        raise KeyboardInterrupt()
    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, interrupted)
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        print('INTERRUPTED: no public result accepted', file=sys.stderr)
        sys.exit(130)
    except (ValueError, OSError, RuntimeError) as exc:
        print("CHECK_ERROR: " + str(exc), file=sys.stderr)
        sys.exit(2)
    finally:
        # Also covers an interrupt arriving while run_child's finally begins.
        for child in list(ACTIVE):
            stop(child)

#!/usr/bin/env python3
"""Offline campaign CLI; JSON stdin/stdout, diagnostics on stderr."""
import json
import math
from pathlib import Path
import sys
sys.path.insert(0, str(Path(__file__).resolve().parent / "src"))
from eywa.offline import execute

def pairs(items):
    d = {}
    for key, value in items:
        if key in d: raise ValueError("duplicate key")
        d[key] = value
    return d

def main():
    try:
        raw = sys.stdin.buffer.read(64 * 1024 * 1024 + 1)
        if len(raw) > 64 * 1024 * 1024: raise ValueError("input cap")
        def bad(value): raise ValueError("nonfinite")
        def finite(value):
            result = float(value)
            if not math.isfinite(result): raise ValueError("nonfinite")
            return result
        request = json.loads(raw.decode("utf-8"), object_pairs_hook=pairs, parse_constant=bad, parse_float=finite)
    except (ValueError, UnicodeError, RecursionError):
        result = {"error": "INVALID_INPUT"}
    else:
        result = execute(request)
    json.dump(result, sys.stdout, ensure_ascii=True, separators=(",", ":"), allow_nan=False)
    sys.stdout.write("\n")
if __name__ == "__main__": main()
# Eywa offline campaign toolkit

The editable package is under src/eywa. campaign_cli.py supplies JSON framing
and adds the local src directory, so no installation is necessary. Run it with
Python 3.11.14. All runtime dependencies are in the standard library.

ast.py defines model types, parameters, expressions and expression evaluation.
oracles.py contains the symbolic type/aggregate visitors and inverse reader.
composer.py owns module dependencies; regex.py owns regular-language objects.
run.py handles corpus identity; state.py prepares stateful replay preambles.
wire.py and offline.py are the incomplete transport/pipeline extension points.
Several existing subsystem assumptions also need repair for the full profile.

The authoritative behavior and output contract are in /workspace/PROTOCOL.md.
All project files may be edited or reorganized. The output certificate is the
interface; private verifier code is never an import dependency.
"""Eywa offline typed model toolkit."""
from .ast import *
from .composer import DependencyGraph

import uuid
from ast import NodeVisitor
from typing import List, Union, Any, Dict, Callable
import eywa.regex as re

class Type(object):
    """
    An Eywa type for a parameter to a function.
    """
    @staticmethod
    def inner(type):
        """
        Look past any type aliases to get the inner type.
        """
        while isinstance(type, Alias):
            type = type.type
        return type


class Void(Type):
    """
    A void type representing no value.
    """
    pass


class Bool(Type):
    """
    A boolean type representing true or false.
    """
    pass


class Char(Type):
    """
    A character type representing a single character.
    """
    pass


class Int(Type):
    """
    An integer type representing an unsigned integer of a given size.
    """

    def __init__(self, size: int = None):
        self.size = size


class String(Type):
    """
    A string type representing a string of a given max length.
    """

    def __init__(self, maxsize: int = 6):
        if maxsize < 0:
            raise Exception('invalid string type')
        self.maxsize = maxsize
        self.char_type = Char()


class Enum(Type):
    """
    An enumeration type representing a choice of values.
    """

    def __init__(self, name: str, values: List[str]):
        self.name = name
        self.values = values


class Array(Type):
    """
    An array type representing an array of a given element type and size.
    """

    def __init__(self, element_type: Type, maxsize: int):
        self.maxsize = maxsize
        self.element_type = element_type


class Struct(Type):
    """
    A struct type representing a struct with a given name and fields.
    """

    def __init__(self, name: str, **kwargs: Type):
        self.name = name
        self.fields = kwargs


class Alias(Type):
    """
    An alias type representing an alias to another type.
    """

    def __init__(self, name: str, type: Type, description=None):
        self.name = name
        self.type = type
        self.description = description


class Expr(object):
    """
    A simple expression class.
    """

    @staticmethod
    def eval(expr, assignment: Dict[str, Any]) -> bool:
        """
        Evaluate an Eywa expression given an assignment of variables.
        """
        return Evaluator(assignment).visit(expr)

    @staticmethod
    def convert(other):
        """
        Ensures that the given object can be converted to an expression.
        """
        if isinstance(other, Expr):
            return other
        if isinstance(other, int):
            return Const(Int(32), other)
        if isinstance(other, Parameter):
            return Var(Type.inner(other.type), other.name)
        raise Exception(f'invalid expression: {other}')

    @staticmethod
    def has_match(type):
        """
        Determines if this expression has a match expression.
        """
        return HasMatch().visit(type)

    def __add__(self, other):
        """
        Override the + operator to create a binary operation expression.
        """
        return Binop(self.type, '+', self, Expr.convert(other))

    def __sub__(self, other):
        """
        Override the - operator to create a binary operation expression.
        """
        return Binop(self.type, '-', self, Expr.convert(other))

    def __and__(self, other):
        """
        Override the & operator to create a binary operation expression.
        """
        return Binop(self.type, '&', self, Expr.convert(other))

    def __or__(self, other):
        """
        Override the | operator to create a binary operation expression.
        """
        return Binop(self.type, '|', self, Expr.convert(other))

    def __le__(self, other):
        """
        Override the <= operator to create a binary operation expression.
        """
        return Binop(Bool(), '<=', self, Expr.convert(other))

    def __lt__(self, other):
        """
        Override the < operator to create a binary operation expression.
        """
        return Binop(Bool(), '<', self, Expr.convert(other))

    def __ge__(self, other):
        """
        Override the >= operator to create a binary operation expression.
        """
        return Binop(Bool(), '>=', self, Expr.convert(other))

    def __gt__(self, other):
        """
        Override the > operator to create a binary operation expression.
        """
        return Binop(Bool(), '>', self, Expr.convert(other))

    def __eq__(self, other):
        """
        Override the == operator to create a binary operation expression.
        """
        return Binop(Bool(), '==', self, Expr.convert(other))

    def __ne__(self, other):
        """
        Override the != operator to create a binary operation expression.
        """
        return Binop(Bool(), '!=', self, Expr.convert(other))

    def get_field(self, field: str):
        """
        A helper function to create a field dereference.
        """
        return Field(self.type.fields[field], self, field)

    def __invert__(self):
        """
        Override the bool operator to create a unary negation expression.
        """
        return Not(Bool(), self)

    def matches(self, regex: re.Regex):
        """
        A helper function to create a match constraint.
        """
        return Match(Bool(), self, regex)

    def forall(self, invariant):
        """
        A helper function to create an array forall expression.
        """
        return Forall(Bool(), self, invariant)

    def implies(self, other):
        """
        A helper function to create an implies expression.
        """
        return Binop(Bool(), '|', Not(Bool(), self), other)


class Var(Expr):
    """
    A variable expression.
    """

    def __init__(self, type, parameter_name):
        self.type = type
        self.parameter_name = parameter_name


class Const(Expr):
    """
    A constant expression.
    """

    def __init__(self, type, constant):
        if isinstance(type, String) and not isinstance(constant, str):
            raise Exception('Constant expression type mismatch')
        if isinstance(type, Int) and not isinstance(constant, int):
            raise Exception('Constant expression type mismatch')
        self.type = type
        self.constant = constant


class Not(Expr):
    """
    A not expression.
    """

    def __init__(self, type, expr: Expr):
        if not isinstance(type, Bool):
            raise Exception('Not expression expected bool return type')
        self.type = type
        self.expr = expr


class Match(Expr):
    """
    A expr for a regular expression match.
    """

    def __init__(self, type, expr: Expr, regex: re.Regex):
        if not isinstance(type, Bool):
            raise Exception('Match expression expected bool return type')
        if not isinstance(expr.type, String):
            raise Exception('Match expression expected string type')
        self.type = type
        self.expr = expr
        self.regex = regex


class Binop(Expr):
    """
    A binary operation expression.
    """

    def __init__(self, type, op: str, left: Expr, right: Expr):
        self.type = type
        self.op = op
        self.left = left
        self.right = right


class Field(Expr):
    """
    A field dereference expression.
    """

    def __init__(self, type, expr: Expr, field: str):
        if not isinstance(expr.type, Struct):
            raise Exception('Field expression expected struct type')
        if type != expr.type.fields[field]:
            raise Exception('Field expression expected field type to match')
        self.type = type
        self.expr = expr
        self.field = field


class Forall(Expr):
    """
    An array forall expression.
    """

    def __init__(self, type, expr, invariant: Callable[[Expr], Expr]):
        if not isinstance(type, Bool):
            raise Exception('forall expression expected bool return type')
        if not isinstance(expr.type, Array):
            raise Exception('forall expression expected array type')
        self.type = type
        self.array_expr = Expr.convert(expr)
        self.invariant = invariant

class Evaluator(NodeVisitor):
    """
    A class that evaluates an Eywa Expression and returns a boolean.
    """

    def __init__(self, assignment):
        self.assignment = assignment

    def visit_Var(self, node):
        return self.assignment[node.parameter_name]

    def visit_Const(self, node):
        return node.constant

    def visit_Not(self, node):
        return not self.visit(node.expr)

    def visit_Match(self, node):
        return re.ismatch(node.regex, self.visit(node.expr))

    def visit_Field(self, node):
        return self.visit(node.expr)[node.field]

    def visit_Forall(self, node):
        old = self.assignment
        array = self.visit(node.array_expr)
        for element in array:
            var = Var(Type.inner(node.array_expr.type.element_type), uuid.uuid4())
            self.assignment = old.copy()
            self.assignment[var.parameter_name] = element
            expr = node.invariant(var)
            if not self.visit(expr):
                return False
        self.assignment = old
        return True

    def visit_Binop(self, node):
        e1 = self.visit(node.left)
        e2 = self.visit(node.right)
        if node.op == '==':
            return e1 == e2
        elif node.op == '!=':
            return e1 != e2
        elif node.op == '>':
            return e1 > e2
        elif node.op == '<':
            return e1 < e2
        elif node.op == '>=':
            return e1 >= e2
        elif node.op == '<=':
            return e1 <= e2
        elif node.op == '+':
            return e1 + e2
        elif node.op == '-':
            return e1 - e2
        elif node.op == '&':
            return e1 and e2
        elif node.op == '|':
            return e1 or e2
        raise Exception(f'Unknown binary operator: {node.op}')


class HasMatch(NodeVisitor):
    """
    A class that checks if an Eywa Expression has a match expression.
    """

    def visit_Var(self, node): return False
    def visit_Const(self, node): return False
    def visit_Match(self, node): return True
    def visit_Not(self, node): return self.visit(node.expr)
    def visit_Field(self, node): return self.visit(node.expr)

    def visit_Binop(self, node): return self.visit(
        node.left) or self.visit(node.right)
    def visit_Forall(self, node): return self.visit(node.array_expr) or self.visit(
        node.invariant(Var(Type.inner(node.array_expr.type.element_type), uuid.uuid4())))


class Parameter:
    """
    An Eywa parameter to a function.
    """

    def __init__(self, name: str, type: Type, description: Union[str, None] = None):
        self.name = name
        self.type = type
        self.description = description

    def __add__(self, other):
        """
        Override the + operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '+', Expr.convert(self), Expr.convert(other))

    def __sub__(self, other):
        """
        Override the - operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '-', Expr.convert(self), Expr.convert(other))

    def __and__(self, other):
        """
        Override the & operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '&', Expr.convert(self), Expr.convert(other))

    def __or__(self, other):
        """
        Override the | operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '|', Expr.convert(self), Expr.convert(other))

    def __le__(self, other):
        """
        Override the <= operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '<=', Expr.convert(self), Expr.convert(other))

    def __lt__(self, other):
        """
        Override the < operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '<', Expr.convert(self), Expr.convert(other))

    def __ge__(self, other):
        """
        Override the >= operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '>=', Expr.convert(self), Expr.convert(other))

    def __gt__(self, other):
        """
        Override the > operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '>', Expr.convert(self), Expr.convert(other))

    def __eq__(self, other):
        """
        Override the == operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '==', Expr.convert(self), Expr.convert(other))

    def __ne__(self, other):
        """
        Override the != operator to create a binary operation expression.
        """
        return Binop(Type.inner(self.type), '!=', Expr.convert(self), Expr.convert(other))

    def __invert__(self):
        """
        Override the bool operator to create a unary negation expression.
        """
        return Not(Bool(), Expr.convert(self))

    def matches(self, regex: re.Regex) -> Expr:
        """
        A helper function to create a match constraint.
        """
        return Match(Bool(), Expr.convert(self), regex)

    def get_field(self, field: str) -> Expr:
        """
        A helper function to create a field dereference.
        """
        return Field(Type.inner(self.type.fields[field]), Expr.convert(self), field)

    def forall(self, invariant: Callable[[Expr], Expr]) -> Expr:
        """
        A helper function to create an array forall expression.
        """
        return Forall(Bool(), Expr.convert(self), invariant)

    def implies(self, other) -> Expr:
        """
        A helper function to create an implies expression.
        """
        return Binop(Type.inner(self.type), '|', Not(Bool(), Expr.convert(self)), Expr.convert(other))


